#include <bits/stdc++.h>

void solve(__int128 n, __int128 a, __int128 b, __int128 c, __int128 &f) {
    if (n < 0) { f = 0; return; }
    if (a >= c || b >= c) {
        solve(n, a % c, b % c, c, f);
        f += (a / c) * (n * (n + 1) / 2) + (b / c) * (n + 1);
    } else if (a) {
        __int128 m = (a * n + b) / c;
        solve(m - 1, c, c - b - 1, a, f);
        f = n * m - f;
    }
}

